import{_ as a,o as t,c as i,a2 as o}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"Login Logs","description":"","frontmatter":{"title":"Login Logs"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/login-logs.md","filePath":"operations-knowledge-base/presales-support/login-logs.md","lastUpdated":1794292919000}'),r={name:"operations-knowledge-base/presales-support/login-logs.md"};function n(s,e,c,l,d,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h2 id="_1-overview" tabindex="-1">1. Overview <a class="header-anchor" href="#_1-overview" aria-label="Permalink to &quot;1. Overview&quot;">​</a></h2><p>The “Login Logs” feature is an important part of the platform’s account security management system. It provides users with detailed records of account login activity.</p><p>Through this feature, users can review their login history, monitor account activity, and identify abnormal or unauthorized login attempts in a timely manner, helping to protect account security.</p><h2 id="_2-access-path" tabindex="-1">2. Access Path <a class="header-anchor" href="#_2-access-path" aria-label="Permalink to &quot;2. Access Path&quot;">​</a></h2><p>Users can access the “Login Logs” page through the following path:</p><p>Top-right profile avatar → Others → Login Logs</p><p>On this page, users can view all login records associated with their account.</p><h2 id="_3-interface-and-feature-description" tabindex="-1">3. Interface and Feature Description <a class="header-anchor" href="#_3-interface-and-feature-description" aria-label="Permalink to &quot;3. Interface and Feature Description&quot;">​</a></h2><h3 id="_1-time-filter-and-search" tabindex="-1">(1) Time Filter and Search <a class="header-anchor" href="#_1-time-filter-and-search" aria-label="Permalink to &quot;(1) Time Filter and Search&quot;">​</a></h3><p>At the top of the page, there is a time selection field where users can select a specific date range (e.g., 2025/07/24 - 2025/07/24).</p><p>After selecting the desired time range, click the “Search” button to filter and display login records within that period, making it easier to review login activity for a specific timeframe.</p><h3 id="_2-login-record-list" tabindex="-1">(2) Login Record List <a class="header-anchor" href="#_2-login-record-list" aria-label="Permalink to &quot;(2) Login Record List&quot;">​</a></h3><p>Login records are displayed in a list format and include the following key information:</p><h4 id="date" tabindex="-1">Date <a class="header-anchor" href="#date" aria-label="Permalink to &quot;Date&quot;">​</a></h4><p>Shows the exact time of each login attempt, including year, month, day, hour, minute, and second (e.g., 2025-07-23 10:15:56), helping users track login activity accurately.</p><h4 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to &quot;Description&quot;">​</a></h4><p>Displays the result of the login action, such as “User login successful”, so users can see whether the login attempt was completed successfully.</p><h4 id="username" tabindex="-1">Username <a class="header-anchor" href="#username" aria-label="Permalink to &quot;Username&quot;">​</a></h4><p>Shows the username of the account that performed the login action.</p><h4 id="login-ip-address" tabindex="-1">Login IP Address <a class="header-anchor" href="#login-ip-address" aria-label="Permalink to &quot;Login IP Address&quot;">​</a></h4><p>Records the IP address used during the login attempt. Users can use this information to determine whether the login was made by themselves or an authorized user in a familiar network environment. If an unfamiliar IP address appears, users should remain alert and check the security of their account promptly.</p><h2 id="_4-important-notes" tabindex="-1">4. Important Notes <a class="header-anchor" href="#_4-important-notes" aria-label="Permalink to &quot;4. Important Notes&quot;">​</a></h2><h3 id="regular-monitoring" tabindex="-1">Regular Monitoring <a class="header-anchor" href="#regular-monitoring" aria-label="Permalink to &quot;Regular Monitoring&quot;">​</a></h3><p>Users are advised to review login logs regularly, especially when any unusual account activity is suspected (e.g., unfamiliar login notifications or unexpected changes to account information).</p><h3 id="handling-suspicious-logins" tabindex="-1">Handling Suspicious Logins <a class="header-anchor" href="#handling-suspicious-logins" aria-label="Permalink to &quot;Handling Suspicious Logins&quot;">​</a></h3><p>If unauthorized or suspicious login records are found (e.g., unknown IP addresses or unfamiliar login times), please contact the platform’s customer service immediately and request an account security check. If necessary, reset the account password to prevent unauthorized access.</p><h3 id="ip-address-identification" tabindex="-1">IP Address Identification <a class="header-anchor" href="#ip-address-identification" aria-label="Permalink to &quot;IP Address Identification&quot;">​</a></h3><p>Users are encouraged to familiarize themselves with their commonly used login IP addresses so they can identify unusual login attempts more quickly. If the source of an IP address is unclear, professional IP lookup tools may be used for further verification.</p><h3 id="information-protection" tabindex="-1">Information Protection <a class="header-anchor" href="#information-protection" aria-label="Permalink to &quot;Information Protection&quot;">​</a></h3><p>Login logs contain sensitive account information (e.g., login times and IP addresses). Users should keep their account login credentials secure to prevent unauthorized access to the login log page and related information.</p><p>Through the “Login Logs” feature, the platform helps users monitor account login activity, identify potential security risks in a timely manner, and improve the overall security and reliability of the account.</p>',31)])])}const g=a(r,[["render",n]]);export{p as __pageData,g as default};
